/**
 * The settings screen (`design/archetypes/settings-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/settings-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type JSX } from 'solid-js'

import { claimSlot, scope } from '@polymorph/solid'
import styles from '@polymorph/recipes/archetypes/settings-page.module.css'
import PageHeader from '../structure/PageHeader'

export interface SettingsPageProps {
  /**
   * `SettingsRow.Group`s.
   */
  children: JSX.Element
  description?: string
  title: string
}

/** The settings screen. */
export default function SettingsPage(given: SettingsPageProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    return (
      <div class={styles.page} data-member="settings-page">
        <PageHeader title={props.title} description={props.description} />
        {props.children}
      </div>
    )
  })
}
